head.script:
//
  tailwind.config = {
    darkMode: 'class',
    theme: {
      extend: {
        colors: {
          terminal: { bg: '#090D16', card: '#111827', border: '#1F2937' },
          bullish: '#10B981',
          bearish: '#EF4444',
          cyanAccent: '#06B6D4',
          goldAccent: '#F59E0B',
          purpleAccent: '#8B5CF6'
        },
        fontFamily: {
          sans: ['Inter', 'sans-serif'],
          mono: ['"JetBrains Mono"', 'monospace']
        }
      }
    }
  };
//

head.b:skin:
:root {
  --bg-terminal: #090D16;
  --bg-card: #111827;
  --border-terminal: #1F2937;
  --bullish: #10B981;
  --bearish: #EF4444;
  --cyan-accent: #06B6D4;
  --gold-accent: #F59E0B;
}
* { box-sizing: border-box; }
body {
  background-color: #090D16;
  color: #F3F4F6;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}
.font-mono-num {
  font-family: 'JetBrains Mono', monospace;
  font-feature-settings: "tnum" 1, "zero" 1;
}
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: #090D16; }
::-webkit-scrollbar-thumb { background: #1F2937; border-radius: 3px; }
@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
.ticker-track {
  display: flex;
  width: max-content;
  animation: ticker-scroll 45s linear infinite;
}
.ticker-container:hover .ticker-track { animation-play-state: paused; }
.glow-emerald { box-shadow: 0 0 18px rgba(16, 185, 129, 0.2); }
@keyframes tick-flash-green {
  0% { color: #34D399; text-shadow: 0 0 12px rgba(52, 211, 153, 0.85); transform: scale(1.02); }
  100% { text-shadow: none; transform: scale(1); }
}
.flash-tick { animation: tick-flash-green 0.75s ease-out; }
@keyframes shimmer-sweep {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(250%); }
}
.shimmer-bar { position: relative; overflow: hidden; }
.shimmer-bar::after {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 45%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  animation: shimmer-sweep 2.2s infinite ease-in-out;
}
@keyframes tape-slide-in {
  0% { opacity: 0; transform: translateY(-8px); background-color: rgba(16, 185, 129, 0.25); }
  100% { opacity: 1; transform: translateY(0); background-color: transparent; }
}
.tape-entry-new { animation: tape-slide-in 0.8s ease-out forwards; }
.poster-frame {
  position: relative;
  overflow: hidden;
  border-radius: 0.5rem;
  border: 1px solid #1F2937;
  background: linear-gradient(145deg, #0f172a, #090d16);
}
.poster-frame img { transition: transform 0.5s ease; }
.poster-frame:hover img { transform: scale(1.04); }
.adsense-wrapper {
  background: #0d131f;
  border: 1px dashed #263345;
  border-radius: 6px;
}
.badge-bullish {
  background-color: rgba(16, 185, 129, 0.08);
  color: #10B981;
  border: 1px solid rgba(16, 185, 129, 0.3);
}
.badge-bearish {
  background-color: rgba(239, 68, 68, 0.08);
  color: #EF4444;
  border: 1px solid rgba(239, 68, 68, 0.3);
}
.blogger-post-body p { margin-bottom: 1rem; color: #D1D5DB; line-height: 1.75; }
.blogger-post-body h2, .blogger-post-body h3 { color: #FFFFFF; font-weight: 700; margin-top: 1.5rem; margin-bottom: 0.75rem; }
.blogger-post-body a { color: #06B6D4; text-decoration: underline; }
.blogger-post-body ul { list-style-type: disc; padding-left: 1.5rem; margin-bottom: 1rem; color: #D1D5DB; }

body.script:
