      { id: "drishyam-3", title: "Drishyam 3", poster: "https://upload.wikimedia.org/wikipedia/en/d/d9/Drishyam-_The_Conclusion_poster.jpg", releaseDate: "2026-10-02", dayCount: 40, category: "Pan-India", classification: "Holdover Benchmark", sentiment: "BULLISH", orderBlock: "Lifetime Accumulation", verdict: "All-Time Blockbuster", dayNet: "₹0.48 Cr", totalNet: "₹215.80 Cr", worldwide: "₹348.90 Cr", baseNetNum: 215.80, baseWwNum: 348.90, ticketsPerMin: 7, dayChange: -15.1, shows: 820, occupancy: 38.6, dominantMarket: "Hindi / Overseas", supportLevel: "₹0.40 Cr", resistanceLevel: "₹350 Cr WW", sparkline: [1.4, 1.2, 1.0, 0.85, 0.70, 0.58, 0.48] },
      { id: "scene-2026", title: "Scene", poster: "https://upload.wikimedia.org/wikipedia/en/3/3b/Scene_%282026_film%29.jpg", releaseDate: "2026-11-06", dayCount: 5, category: "Regional", classification: "Last 15 Days", sentiment: "BEARISH", orderBlock: "Retail Liquidation", verdict: "Heavy Drop", dayNet: "₹1.45 Cr", totalNet: "₹12.85 Cr", worldwide: "₹15.20 Cr", baseNetNum: 12.85, baseWwNum: 15.20, ticketsPerMin: 12, dayChange: -40.0, shows: 2840, occupancy: 18.2, dominantMarket: "Tamil / Malayalam", supportLevel: "₹1.2 Cr", resistanceLevel: "₹25 Cr Net", sparkline: [4.2, 3.8, 3.1, 2.3, 1.45] },
      { id: "mookuthi-amman-2", title: "Mookuthi Amman 2", poster: "https://upload.wikimedia.org/wikipedia/en/e/ef/Mookuthi_Amman_2_poster.jpg", releaseDate: "2026-11-06", dayCount: 5, category: "Regional", classification: "Last 15 Days", sentiment: "BEARISH", orderBlock: "Order Block Breakdown", verdict: "Severe Capitulation", dayNet: "₹0.24 Cr", totalNet: "₹2.10 Cr", worldwide: "₹2.65 Cr", baseNetNum: 2.10, baseWwNum: 2.65, ticketsPerMin: 3, dayChange: -59.2, shows: 1150, occupancy: 9.4, dominantMarket: "Tamil", supportLevel: "₹0.20 Cr", resistanceLevel: "₹5.0 Cr Net", sparkline: [0.85, 0.60, 0.52, 0.38, 0.24] },
      { id: "ak-47", title: "Aadarsha Kutumbam (AK 47)", poster: "https://upload.wikimedia.org/wikipedia/en/0/06/Aadarsha_Kutumbam_poster.jpg", releaseDate: "2026-10-30", dayCount: 12, category: "Regional", classification: "Last 15 Days", sentiment: "BEARISH", orderBlock: "Volume Exhaustion", verdict: "Weekday Bleed", dayNet: "₹0.62 Cr", totalNet: "₹18.40 Cr", worldwide: "₹22.10 Cr", baseNetNum: 18.40, baseWwNum: 22.10, ticketsPerMin: 8, dayChange: -18.5, shows: 1820, occupancy: 21.0, dominantMarket: "Telugu", supportLevel: "₹0.50 Cr", resistanceLevel: "₹25 Cr Net", sparkline: [3.4, 2.9, 2.1, 1.6, 1.1, 0.8, 0.62] },
      { id: "pyre", title: "Pyre", poster: "https://upload.wikimedia.org/wikipedia/en/2/28/Pyre_Film_Poster.jpg", releaseDate: "2026-10-30", dayCount: 12, category: "Regional", classification: "Last 15 Days", sentiment: "BEARISH", orderBlock: "Screen Compression", verdict: "Screen Loss", dayNet: "₹0.31 Cr", totalNet: "₹9.65 Cr", worldwide: "₹11.80 Cr", baseNetNum: 9.65, baseWwNum: 11.80, ticketsPerMin: 4, dayChange: -32.1, shows: 940, occupancy: 14.8, dominantMarket: "Hindi Multiplex", supportLevel: "₹0.25 Cr", resistanceLevel: "₹15 Cr Net", sparkline: [1.8, 1.5, 1.2, 0.9, 0.6, 0.45, 0.31] },
      { id: "jailer-2", title: "Jailer 2", poster: "https://upload.wikimedia.org/wikipedia/en/d/dc/Jailer_2_poster.jpg", releaseDate: "2026-10-15", dayCount: 27, category: "Pan-India", classification: "Holdover Benchmark", sentiment: "BEARISH", orderBlock: "Distribution Plateau", verdict: "All-Time Super Hit", dayNet: "₹1.15 Cr", totalNet: "₹472.53 Cr", worldwide: "₹695.40 Cr", baseNetNum: 472.53, baseWwNum: 695.40, ticketsPerMin: 14, dayChange: -29.6, shows: 2450, occupancy: 29.5, dominantMarket: "Tamil / Telugu", supportLevel: "₹1.00 Cr", resistanceLevel: "₹700 Cr WW", sparkline: [4.5, 3.8, 3.2, 2.6, 2.1, 1.6, 1.15] },
      { id: "udta-teer", title: "Udta Teer", poster: "https://upload.wikimedia.org/wikipedia/en/c/c8/Udta_Teer_film_poster.jpg", releaseDate: "2026-10-23", dayCount: 19, category: "Pan-India", classification: "Holdover Benchmark", sentiment: "BEARISH", orderBlock: "Order Absorption", verdict: "Steady Tail Hold", dayNet: "₹0.85 Cr", totalNet: "₹34.20 Cr", worldwide: "₹44.80 Cr", baseNetNum: 34.20, baseWwNum: 44.80, ticketsPerMin: 9, dayChange: -22.4, shows: 1380, occupancy: 23.4, dominantMarket: "Hindi North", supportLevel: "₹0.70 Cr", resistanceLevel: "₹40 Cr Net", sparkline: [2.2, 1.9, 1.6, 1.4, 1.1, 0.95, 0.85] }
    ]
  };

  document.addEventListener('DOMContentLoaded', function() {
    initClock();
    loadData();
    bindEvents();
    if (document.getElementById('liveVelocityWaveform')) {
      initLiveWaveform();
      startLiveOdometerEngine();
      startLiveOrderTape();
    }
    initAutoSyncPolling();
  });

  function initClock() {
    const clockEl = document.getElementById('live-ist-clock');
    function update() {
      if (!clockEl) return;
      const now = new Date();
      clockEl.textContent = new Intl.DateTimeFormat('en-IN', {
        timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
      }).format(now) + ' IST';
    }
    update();
    setInterval(update, 1000);
  }

  async function loadData(isBg) {
    if (REMOTE_DATA_URL) {
      try {
        const res = await fetch(REMOTE_DATA_URL + '?t=' + Date.now());
        if (res.ok) {
          const remoteData = await res.json();
          if (remoteData && remoteData.heroMovie) {
            if (!/^https?:\/\//i.test(remoteData.heroMovie.poster || '')) {
              remoteData.heroMovie.poster = FALLBACK_DATA.heroMovie.poster;
            }
            (remoteData.marketReleases || []).concat(remoteData.archivedReleases || []).forEach(function(rm) {
              if (!/^https?:\/\//i.test(rm.poster || '')) {
                const fbList = (FALLBACK_DATA.marketReleases || []).concat(FALLBACK_DATA.archivedReleases || []);
                const fb = fbList.find(function(x) { return x.id === rm.id; });
                rm.poster = fb ? fb.poster : FALLBACK_DATA.heroMovie.poster;
              }
            });
            boxOfficeData = remoteData;
          }
        }
      } catch (e) {}
    }
    if (!boxOfficeData) boxOfficeData = FALLBACK_DATA;
    if (!currentHeroMovie || !isBg || currentHeroMovie.id === boxOfficeData.heroMovie.id) {
      currentHeroMovie = boxOfficeData.heroMovie;
      const lv = currentHeroMovie.liveVelocity || {};
      if (typeof lv.baseIndiaNetCr === 'number' && (!isBg || lv.baseIndiaNetCr > liveIndiaNetAccumulator)) {
        liveIndiaNetAccumulator = lv.baseIndiaNetCr;
      }
      if (typeof lv.baseWorldwideCr === 'number' && (!isBg || lv.baseWorldwideCr > liveWorldwideAccumulator)) {
        liveWorldwideAccumulator = lv.baseWorldwideCr;
      }
    } else {
      const updatedMatch = (boxOfficeData.marketReleases || []).find(function(m) { return m.id === currentHeroMovie.id; });
      if (updatedMatch) {
        currentHeroMovie.daysInTheaters = updatedMatch.dayCount;
        currentHeroMovie.keyMetrics.indiaNet = updatedMatch.totalNet;
        currentHeroMovie.keyMetrics.worldwideTotal = updatedMatch.worldwide;
        if (!isBg || updatedMatch.baseNetNum > liveIndiaNetAccumulator) liveIndiaNetAccumulator = updatedMatch.baseNetNum;
        if (!isBg || updatedMatch.baseWwNum > liveWorldwideAccumulator) liveWorldwideAccumulator = updatedMatch.baseWwNum;
      }
    }

    const syncEl = document.getElementById('footer-last-sync');
    if (syncEl) syncEl.textContent = new Date().toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata' }) + ' IST';

    try { renderTickerTape(); } catch(e) {}
    if (document.getElementById('hero-movie-poster')) {
      try { renderHeroSpotlight(); } catch(e) {}
      try { renderRegionalOccupancy(); } catch(e) {}
      try { renderBoards(); } catch(e) {}
      try { updateDynamicSeo(); } catch(e) {}
    }
  }

  function updateDynamicSeo() {
    if (!boxOfficeData || !boxOfficeData.heroMovie) return;
    const hero = boxOfficeData.heroMovie;
    const active = boxOfficeData.marketReleases || [];
    const topNames = active.slice(0, 4).map(function(m) { return m.title + ' (Day ' + m.dayCount + ': ' + m.totalNet + ')'; }).join(', ');

    document.title = hero.title + ' Day ' + hero.daysInTheaters + ' Box Office Collection (' + hero.keyMetrics.indiaNet + ' Net, ' + hero.keyMetrics.worldwideTotal + ' WW) | BoxOfficeCollectionLive';

    const descText = 'Live Indian Box Office Collection updates: ' + topNames + '. Check day-wise India Net, Worldwide Gross, occupancy, and BookMyShow buzz.';
    let metaDesc = document.querySelector('meta[name="description"]');
    if (!metaDesc) {
      metaDesc = document.createElement('meta');
      metaDesc.name = 'description';
      document.head.appendChild(metaDesc);
    }
    metaDesc.content = descText;

    const seoBox = document.getElementById('seo-summary-cards');
    if (seoBox) {
      seoBox.innerHTML = active.slice(0, 6).map(function(m) {
        return '<article class="bg-[#090D16] border border-[#1F2937] rounded p-3 space-y-1"><h3 class="text-sm font-bold text-white">' + m.title + ' Day ' + m.dayCount + ' Box Office Collection</h3><p class="text-xs text-gray-400 leading-relaxed">' + m.title + ' has collected <strong>' + m.totalNet + ' India Net</strong> and <strong>' + m.worldwide + ' Worldwide</strong> across ' + (m.shows || 0).toLocaleString('en-IN') + ' shows (' + m.occupancy + '% occupancy). Latest single-day estimate: <strong>' + m.dayNet + '</strong> (' + m.verdict + ').</p></article>';
      }).join('');
    }

    const faqEntities = active.slice(0, 5).map(function(m) {
      return {
        '@type': 'Question',
        name: 'What is ' + m.title + ' Day ' + m.dayCount + ' box office collection?',
        acceptedAnswer: {
          '@type': 'Answer',
          text: m.title + ' collected ' + m.dayNet + ' on Day ' + m.dayCount + ', taking its total to ' + m.totalNet + ' India Net and ' + m.worldwide + ' Worldwide.'
        }
      };
    });
    const schemaPayload = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'FAQPage',
          mainEntity: faqEntities
        },
        {
          '@type': 'ItemList',
          name: 'Live Indian Box Office Collections',
          itemListElement: active.slice(0, 8).map(function(m, idx) {
            return { '@type': 'ListItem', position: idx + 1, name: m.title + ' - ' + m.totalNet + ' India Net (' + m.worldwide + ' WW)' };
          })
        }
      ]
    };
    let ldEl = document.getElementById('dynamic-boxoffice-schema');
    if (!ldEl) {
      ldEl = document.createElement('script');
      ldEl.type = 'application/ld+json';
      ldEl.id = 'dynamic-boxoffice-schema';
      document.head.appendChild(ldEl);
    }
    ldEl.textContent = JSON.stringify(schemaPayload);
  }

  function initAutoSyncPolling() {
    const cdEl = document.getElementById('auto-sync-countdown');
    setInterval(async function() {
      if (!autoSyncEnabled) return;
      autoSyncSecondsLeft--;
      if (autoSyncSecondsLeft <= 0) {
        autoSyncSecondsLeft = 30;
        await loadData(true);
      }
      if (cdEl) cdEl.textContent = autoSyncSecondsLeft + 's';
    }, 1000);
  }

  function startLiveOdometerEngine() {
    setInterval(function() {
      if (!currentHeroMovie) return;
      const tix = (currentHeroMovie.liveVelocity && currentHeroMovie.liveVelocity.ticketsPerMin) ? currentHeroMovie.liveVelocity.ticketsPerMin : 15;
      const inc = (tix / 148) * (0.0001 + Math.random() * 0.0003);
      liveIndiaNetAccumulator += inc * 0.65;
      liveWorldwideAccumulator += inc;
      updateLiveNumbersDisplay(true);
    }, 1400);
  }

  function updateLiveNumbersDisplay(flash) {
    function fmt(v) {
      if (isUsdCurrency) return '$' + ((v * 10) / USD_INR_RATE).toFixed(4) + 'M';
      return '₹' + v.toFixed(4) + ' Cr';
    }
    const pairs = [
      ['hero-india-net', fmt(liveIndiaNetAccumulator)],
      ['hero-poster-live-net', fmt(liveIndiaNetAccumulator)],
      ['hero-worldwide', fmt(liveWorldwideAccumulator) + '+'],
      ['hero-poster-live-ww', fmt(liveWorldwideAccumulator) + '+']
    ];
    pairs.forEach(function(p) {
      const el = document.getElementById(p[0]);
      if (el) {
        el.textContent = p[1];
        if (flash) {
          el.classList.remove('flash-tick');
          void el.offsetWidth;
          el.classList.add('flash-tick');
        }
      }
    });
  }

  function initLiveWaveform() {
    const canvas = document.getElementById('liveVelocityWaveform');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    function resize() {
      canvas.width = canvas.parentElement.clientWidth;
      canvas.height = canvas.parentElement.clientHeight;
    }
    resize();
    window.addEventListener('resize', resize);
    const bars = new Array(40).fill(20);
    let phase = 0;
    function draw() {
      const w = canvas.width, h = canvas.height;
      ctx.clearRect(0, 0, w, h);
      phase += 0.08;
      if (waveformSpikeIntensity > 0) {
        bars[bars.length - 1] = Math.min(h - 10, 40 + waveformSpikeIntensity * 35);
        waveformSpikeIntensity *= 0.85;
      }
      if (Math.random() > 0.72) {
        bars.shift();
        bars.push(18 + Math.random() * 32 + waveformSpikeIntensity * 25);
      }
      const bw = w / bars.length;
      bars.forEach(function(val, i) {
        ctx.fillStyle = i > bars.length - 4 ? 'rgba(16,185,129,0.45)' : 'rgba(6,182,212,0.18)';
        ctx.fillRect(i * bw + 1, h - Math.min(h - 8, val), bw - 2, Math.min(h - 8, val));
      });
      ctx.beginPath();
      ctx.strokeStyle = '#10B981';
      ctx.lineWidth = 2;
      for (let x = 0; x < w; x += 4) {
        const idx = Math.min(bars.length - 1, Math.floor((x / w) * bars.length));
        const y = h * 0.52 - Math.sin(x * 0.045 - phase) * (bars[idx] * 0.4);
        if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
      requestAnimationFrame(draw);
    }
    draw();
  }

  function startLiveOrderTape() {
    const tapeEl = document.getElementById('live-order-tape');
    if (!tapeEl) return;
    const cities = [
      { c: "MUMBAI IMAX 3D", a: "₹24,800", s: 42 },
      { c: "BENGALURU 3D", a: "₹31,400", s: 68 },
      { c: "HYDERABAD AMB", a: "₹28,500", s: 54 },
      { c: "NCR DELHI", a: "₹19,200", s: 24 },
      { c: "CHENNAI LUXE", a: "₹16,800", s: 38 }
    ];
    function push() {
      const p = cities[Math.floor(Math.random() * cities.length)];
      const t = new Date().toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false });
      const sym = currentHeroMovie ? currentHeroMovie.title.split(' ')[0] : 'RAMAYANA';
      const row = document.createElement('div');
      row.className = 'tape-entry-new flex justify-between px-1.5 py-0.5 border-b border-[#1F2937]/50';
      row.innerHTML = '<span class="text-gray-400">' + t + ' • <strong class="text-gray-200">' + p.c + '</strong> (' + sym + ')</span><span class="text-emerald-400 font-bold">+' + p.a + ' (' + p.s + ' tix)</span>';
      tapeEl.prepend(row);
      waveformSpikeIntensity = 1.0;
      while (tapeEl.children.length > 4) tapeEl.removeChild(tapeEl.lastChild);
    }
    push();
    setInterval(push, 1800);
  }

  function renderTickerTape() {
    const el = document.getElementById('ticker-track-el');
    if (!el || !boxOfficeData.tickerFeed) return;
    const items = [...boxOfficeData.tickerFeed, ...boxOfficeData.tickerFeed, ...boxOfficeData.tickerFeed];
    el.innerHTML = items.map(function(i) {
      const bull = i.change >= 0;
      return '<div class="inline-flex items-center gap-3 px-4 border-r border-[#1F2937]/80"><span class="font-bold text-white">' + i.symbol + '</span><span class="text-gray-400">' + i.day + '</span><span class="font-bold text-white">' + i.collection + '</span><span class="' + (bull ? 'text-emerald-400' : 'text-red-400') + ' font-bold">' + (bull ? '▲ +' : '▼ ') + i.change.toFixed(1) + '%</span></div>';
    }).join('');
  }

  function renderHeroSpotlight() {
    const m = currentHeroMovie;
    if (!m) return;
    document.getElementById('hero-movie-poster').src = m.poster;
    document.getElementById('hero-poster-day-badge').textContent = 'DAY ' + m.daysInTheaters;
    const tix = m.liveVelocity ? m.liveVelocity.ticketsPerMin : 15;
    const sec = m.liveVelocity ? m.liveVelocity.inrPerSecond : 8500;
    document.getElementById('poster-velocity-tix').textContent = '⚡ ' + tix + ' TIX / MIN';
    document.getElementById('poster-velocity-inr').textContent = '+₹' + sec.toLocaleString('en-IN') + ' / SEC';
    document.getElementById('header-live-velocity').textContent = tix + ' TIX/MIN';
    document.getElementById('hero-movie-title').textContent = m.title;
    document.getElementById('hero-movie-subtitle').textContent = m.subtitle;
    document.getElementById('hero-sentiment-badge').textContent = m.sentiment;
    document.getElementById('hero-release-meta').textContent = 'RELEASED: ' + m.releaseDate + ' (DAY ' + m.daysInTheaters + ')';
    document.getElementById('hero-movie-tagline').textContent = m.orderBlockVerdict;
    updateLiveNumbersDisplay(false);
    document.getElementById('hero-india-gross').textContent = m.keyMetrics.indiaGross;
    document.getElementById('hero-overseas-gross').textContent = m.keyMetrics.overseasGross;
    document.getElementById('hero-show-count').textContent = m.keyMetrics.showCount;
    document.getElementById('hero-occupancy').textContent = m.keyMetrics.avgOccupancy;

    const sr = m.supportResistance || {};
    const pct = typeof sr.resistanceProgress === 'number' ? Math.min(100, sr.resistanceProgress) : 75;
    const targetEl = document.getElementById('hero-target-res');
    if (targetEl && sr.targetClubResistance) targetEl.textContent = sr.targetClubResistance + ' (' + pct.toFixed(1) + '%)';
    const supEl = document.getElementById('hero-weekday-sup');
    if (supEl && sr.weekdaySupport) supEl.textContent = sr.weekdaySupport;
    const langBadge = document.getElementById('lang-total-badge');
    if (langBadge && m.keyMetrics) langBadge.textContent = m.keyMetrics.indiaNet + ' Net';
    const resLabel = document.getElementById('resistance-label-text');
    if (resLabel && sr.targetClubResistance) resLabel.textContent = sr.targetClubResistance;
    const resPct = document.getElementById('resistance-pct-text');
    if (resPct) resPct.textContent = pct.toFixed(1) + '% Unlocked';
    const resBar = document.getElementById('resistance-progress-bar');
    if (resBar) resBar.style.width = pct.toFixed(1) + '%';
    const wfRate = document.getElementById('waveform-rate-label');
    if (wfRate) wfRate.textContent = '+₹' + ((sec * 60) / 100000).toFixed(2) + ' Lakhs / Min';
    renderShowTimingOccupancy();
    renderRecordsAndMilestones();

    const langEl = document.getElementById('language-bars-container');
    if (langEl && m.languageBreakdown) {
      langEl.innerHTML = m.languageBreakdown.map(function(l) {
        return '<div class="space-y-1"><div class="flex justify-between text-xs"><span class="text-gray-300 font-semibold">' + l.language + '</span><span class="font-bold" style="color:' + l.color + '">₹' + l.amount.toFixed(2) + ' Cr (' + l.percentage + '%)</span></div><div class="w-full bg-[#111827] h-2 rounded overflow-hidden"><div class="h-full rounded" style="width:' + l.percentage + '%;background-color:' + l.color + '"></div></div></div>';
      }).join('');
    }
    renderHeroChart(m.dayWiseCollections);
  }

  function renderHeroChart(dayData) {
    const canvas = document.getElementById('ramayanaChart');
    if (!canvas || !dayData || typeof Chart === 'undefined') return;
    if (currentChart) currentChart.destroy();
    const vals = dayData.map(function(d) {
      if (activeChartMetric === 'gross') return d.gross;
      if (activeChartMetric === 'shows') return d.shows;
      if (activeChartMetric === 'occupancy') return d.occupancy;
      return d.net;
    });
    currentChart = new Chart(canvas.getContext('2d'), {
      type: 'bar',
      data: {
        labels: dayData.map(function(d) { return d.label; }),
        datasets: [{
          label: activeChartMetric.toUpperCase(),
          data: vals,
          backgroundColor: dayData.map(function(d) { return d.net >= 100 ? 'rgba(245,158,11,0.85)' : (d.change < 0 ? 'rgba(239,68,68,0.6)' : 'rgba(16,185,129,0.35)'); }),
          borderColor: dayData.map(function(d) { return d.net >= 100 ? '#F59E0B' : (d.change < 0 ? '#EF4444' : '#10B981'); }),
          borderWidth: 1.5,
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { ticks: { color: '#9CA3AF' }, grid: { color: 'rgba(31,41,55,0.4)' } },
          y: { ticks: { color: '#9CA3AF' }, grid: { color: 'rgba(31,41,55,0.4)' } }
        }
      }
    });
  }

  function renderRegionalOccupancy() {
    const grid = document.getElementById('regional-occupancy-grid');
    if (!grid || !boxOfficeData.heroMovie.regionalOccupancy) return;
    grid.innerHTML = boxOfficeData.heroMovie.regionalOccupancy.map(function(c) {
      let occ = c.occupancy;
      if (activeOccupancyFormat === '3d') occ = Math.min(100, occ + 8.5);
      if (activeOccupancyFormat === '2d') occ = Math.max(10, occ - 6.2);
      const cls = occ >= 80 ? 'text-emerald-400 border-emerald-400 bg-emerald-950/30' : (occ < 55 ? 'text-amber-400 border-amber-500/40 bg-amber-500/10' : 'text-cyan-400 border-cyan-500/40 bg-cyan-500/10');
      return '<div class="bg-[#090D16] border ' + cls + ' p-3 rounded font-mono-num"><div class="flex justify-between text-xs"><strong>' + c.city + '</strong><span>' + c.shows + ' sh</span></div><div class="text-lg font-bold mt-1">' + occ.toFixed(1) + '%</div><div class="text-[9px] text-gray-400 mt-1">' + c.peakTime + '</div></div>';
    }).join('');
    renderShowTimingOccupancy();
  }

  function renderShowTimingOccupancy() {
    const tbody = document.getElementById('show-timing-table-body');
    if (!tbody) return;
    const rows = (currentHeroMovie && currentHeroMovie.showTimingOccupancy && currentHeroMovie.showTimingOccupancy.length)
      ? currentHeroMovie.showTimingOccupancy
      : (boxOfficeData.heroMovie && boxOfficeData.heroMovie.showTimingOccupancy) || [
          { language: 'Hindi (3D)', overall: 44.50, morning: 22.08, afternoon: 51.08, evening: 58.92, night: 45.92 },
          { language: 'Kannada (3D)', overall: 72.66, morning: 51.18, afternoon: 80.00, evening: 81.82, night: 77.64 },
          { language: 'Tamil (3D)', overall: 69.96, morning: 53.45, afternoon: 63.64, evening: 77.91, night: 61.64 },
          { language: 'Telugu (3D)', overall: 28.34, morning: 21.18, afternoon: 26.45, evening: 33.73, night: 32.00 }
        ];
    const delta = activeOccupancyFormat === '3d' ? 4.2 : (activeOccupancyFormat === '2d' ? -5.8 : 0);
    function adj(v) { return Math.max(5, Math.min(99, v + delta)).toFixed(2) + '%'; }
    function colorCls(v) {
      const val = v + delta;
      return val >= 65 ? 'text-emerald-400 font-bold' : (val >= 40 ? 'text-cyan-300 font-semibold' : 'text-amber-400');
    }
    tbody.innerHTML = rows.map(function(r) {
      return '<tr class="bg-[#090D16] hover:bg-[#0d1422]"><td class="py-2.5 px-3 border-r border-[#1F2937] font-bold text-white">' + r.language + '</td><td class="py-2.5 px-3 border-r border-[#1F2937] ' + colorCls(r.overall) + '">' + adj(r.overall) + '</td><td class="py-2.5 px-3 border-r border-[#1F2937] text-gray-300">' + adj(r.morning) + '</td><td class="py-2.5 px-3 border-r border-[#1F2937] text-gray-200">' + adj(r.afternoon) + '</td><td class="py-2.5 px-3 border-r border-[#1F2937] ' + colorCls(r.evening) + '">' + adj(r.evening) + '</td><td class="py-2.5 px-3 text-gray-200">' + adj(r.night) + '</td></tr>';
    }).join('');
  }

  function renderRecordsAndMilestones() {
    const grid = document.getElementById('records-milestones-grid');
    if (!grid) return;
    const items = (currentHeroMovie && currentHeroMovie.recordsAndMilestones && currentHeroMovie.recordsAndMilestones.length)
      ? currentHeroMovie.recordsAndMilestones
      : [
          { label: 'SINGLE-DAY PEAK', value: '₹107.50 Cr (Day 5)', sub: 'Highest Diwali Monday Net ever' },
          { label: 'TOTAL FOOTFALLS', value: '1.97 Crore+', sub: 'Cumulative domestic admissions' },
          { label: 'BMS SINGLE-DAY RECORD', value: '16.60 Lakh Tix', sub: 'Surpasses previous all-time peak' },
          { label: 'FASTEST BMS HOURLY', value: '1.40 Lakh / Hr', sub: '4 Consecutive 1M+ Ticket Days' }
        ];
    grid.innerHTML = items.map(function(it, idx) {
      const accent = idx < 2 ? 'border-amber-500/40 text-amber-400' : (idx < 4 ? 'border-emerald-500/40 text-emerald-400' : 'border-[#1F2937] text-cyan-400');
      return '<div class="bg-[#090D16] border ' + accent + ' rounded p-3 space-y-1"><div class="text-[10px] font-bold uppercase tracking-wider">' + it.label + '</div><div class="text-sm font-extrabold text-white leading-snug">' + it.value + '</div><div class="text-[10px] text-gray-400 leading-snug">' + (it.sub || '') + '</div></div>';
    }).join('');
  }

  function renderBoards() {
    const bEl = document.getElementById('bullish-cards-container');
    const rEl = document.getElementById('bearish-cards-container');
    if (!bEl || !rEl) return;
    const q = (document.getElementById('movie-search-input') ? document.getElementById('movie-search-input').value : '').toLowerCase();
    const s = document.getElementById('board-sort-select') ? document.getElementById('board-sort-select').value : 'trend-desc';
    const list = boxOfficeData.marketReleases.filter(function(m) {
      if (q && m.title.toLowerCase().indexOf(q) === -1) return false;
      if (activeFilter === 'recent15') return m.classification === 'Last 15 Days';
      if (activeFilter === 'panIndia') return m.category === 'Pan-India';
      if (activeFilter === 'regional') return m.category === 'Regional';
      return true;
    }).sort(function(a, b) {
      if (s === 'trend-desc') return (b.trendScore || b.baseNetNum || 0) - (a.trendScore || a.baseNetNum || 0);
      if (s === 'change-desc') return b.dayChange - a.dayChange;
      if (s === 'change-asc') return a.dayChange - b.dayChange;
      if (s === 'occupancy-desc') return b.occupancy - a.occupancy;
      return b.baseNetNum - a.baseNetNum;
    });
    const bulls = list.filter(function(m) { return m.sentiment === 'BULLISH'; });
    const bears = list.filter(function(m) { return m.sentiment === 'BEARISH'; });
    document.getElementById('bullish-count-badge').textContent = '(' + bulls.length + ')';
    document.getElementById('bearish-count-badge').textContent = '(' + bears.length + ')';

    function card(m, bull) {
      const trendTag = m.googleTrending ? ' <span class="px-1 py-0.5 rounded bg-amber-500/20 text-amber-300 text-[9px]">TRENDING</span>' : (m.bmsBuzzSignals > 0 ? ' <span class="px-1 py-0.5 rounded bg-cyan-500/15 text-cyan-300 text-[9px]">BMS BUZZ</span>' : '');
      return '<div onclick="inspectMovie(\'' + m.id + '\')" class="bg-[#090D16] border border-[#1F2937] hover:border-cyan-500/50 p-3 rounded-lg flex gap-3.5 font-mono-num cursor-pointer transition"><div class="w-20 sm:w-24 h-[120px] sm:h-[144px] shrink-0 poster-frame"><img src="' + m.poster + '" alt="' + m.title + '" onerror="this.src=\'https://upload.wikimedia.org/wikipedia/en/4/48/Ramayana_Part_1_%28poster%29.jpg\'" class="w-full h-full object-cover block"/><div class="absolute bottom-0 inset-x-0 bg-black/90 text-center py-1 text-[11px] font-black text-white">' + m.totalNet + '</div></div><div class="flex-1 min-w-0 flex flex-col justify-between"><div class="flex justify-between items-start gap-2"><div class="min-w-0"><h4 class="font-bold text-white text-sm truncate">' + m.title + trendTag + '</h4><div class="text-[11px] text-gray-400 truncate">' + m.verdict + ' • Day ' + m.dayCount + '</div></div><span class="text-sm font-bold ' + (bull ? 'text-emerald-400' : 'text-red-400') + '">' + (m.dayChange > 0 ? '+' : '') + m.dayChange.toFixed(1) + '%</span></div><div class="grid grid-cols-3 gap-2 pt-2 border-t border-[#1F2937] text-xs"><div><div class="text-[9px] text-gray-500">TODAY</div><div class="font-bold text-white">' + m.dayNet + '</div></div><div><div class="text-[9px] text-gray-500">WORLDWIDE</div><div class="font-bold text-cyan-400">' + m.worldwide + '</div></div><div><div class="text-[9px] text-gray-500">OCCUPANCY</div><div class="font-bold text-gray-200">' + m.occupancy + '%</div></div></div></div></div>';
    }
    bEl.innerHTML = bulls.map(function(m) { return card(m, true); }).join('') || '<p class="text-xs font-mono-num text-gray-500">No active bullish matches. Check Past Releases Archive below.</p>';
    rEl.innerHTML = bears.map(function(m) { return card(m, false); }).join('') || '<p class="text-xs font-mono-num text-gray-500">No active bearish matches. Check Past Releases Archive below.</p>';

    const archSection = document.getElementById('archive-vault-section');
    const archEl = document.getElementById('archive-cards-container');
    const archBadge = document.getElementById('archive-count-badge');
    const archBtn = document.getElementById('toggle-archive-all-btn');
    if (archEl && archSection) {
      const allArch = (boxOfficeData.archivedReleases || []).filter(function(m) {
        return !q || m.title.toLowerCase().indexOf(q) !== -1;
      });
      if (archBadge) archBadge.textContent = '(' + allArch.length + ')';
      const showAll = window._showAllArchive === true || q.length > 0;
      const visibleArch = showAll ? allArch : allArch.slice(0, 6);
      archEl.innerHTML = visibleArch.map(function(m) {
        return card(m, m.sentiment !== 'BEARISH');
      }).join('') || '<p class="text-xs font-mono-num text-gray-500 col-span-full">No matching archived releases yet.</p>';
      if (archBtn) {
        if (allArch.length > 6 && q.length === 0) {
          archBtn.classList.remove('hidden');
          archBtn.textContent = window._showAllArchive ? 'Show Less' : 'Show All (' + allArch.length + ')';
        } else {
          archBtn.classList.add('hidden');
        }
      }
    }
  }

  window.inspectMovie = function(id) {
    const allPool = (boxOfficeData.marketReleases || []).concat(boxOfficeData.archivedReleases || []);
    const m = allPool.find(function(x) { return x.id === id; });
    if (!m) return;
    if (boxOfficeData.heroMovie && id === boxOfficeData.heroMovie.id) {
      currentHeroMovie = boxOfficeData.heroMovie;
      liveIndiaNetAccumulator = currentHeroMovie.liveVelocity.baseIndiaNetCr;
      liveWorldwideAccumulator = currentHeroMovie.liveVelocity.baseWorldwideCr;
    } else {
      liveIndiaNetAccumulator = m.baseNetNum || 0;
      liveWorldwideAccumulator = m.baseWwNum || 0;
      const wwNum = m.baseWwNum || 0;
      const netNum = m.baseNetNum || 0;
      currentHeroMovie = {
        id: m.id, title: m.title.toUpperCase(), poster: m.poster,
        subtitle: m.verdict + ' | ' + (m.category || 'Indian Cinema') + ' | Released ' + (m.releaseDate || ''),
        releaseDate: m.releaseDate,
        daysInTheaters: m.dayCount, sentiment: m.orderBlock || m.classification, orderBlockVerdict: m.verdict,
        liveVelocity: { ticketsPerMin: m.ticketsPerMin || 2, inrPerSecond: (m.ticketsPerMin || 2) * 380 },
        keyMetrics: {
          indiaNet: m.totalNet, indiaGross: '₹' + (netNum * 1.19).toFixed(2) + ' Cr',
          overseasGross: '₹' + Math.max(0, wwNum - netNum * 1.19).toFixed(2) + ' Cr',
          worldwideTotal: m.worldwide, showCount: (m.shows || 0).toLocaleString(), avgOccupancy: (m.occupancy || 0) + '%'
        },
        supportResistance: { targetClubResistance: m.resistanceLevel || 'Lifetime Run', resistanceProgress: Math.min(100, (wwNum / 500) * 100), weekdaySupport: m.supportLevel || 'Archive Vault' },
        dayWiseCollections: (m.sparkline && m.sparkline.length ? m.sparkline : [netNum]).map(function(v, i) { return { label: 'D' + (i + 1), net: v, gross: v * 1.2, change: 0, shows: m.shows || 0, occupancy: m.occupancy || 0 }; }),
        languageBreakdown: [{ language: m.dominantMarket || 'India / Overseas', amount: netNum, percentage: 100, color: '#06B6D4' }]
      };
    }
    renderHeroSpotlight();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  function bindEvents() {
    document.querySelectorAll('.chart-tab').forEach(function(b) {
      b.addEventListener('click', function(e) {
        activeChartMetric = e.target.getAttribute('data-metric');
        if (currentHeroMovie) renderHeroChart(currentHeroMovie.dayWiseCollections);
      });
    });
    document.querySelectorAll('.occupancy-format-tab').forEach(function(b) {
      b.addEventListener('click', function(e) {
        activeOccupancyFormat = e.target.getAttribute('data-format');
        renderRegionalOccupancy();
      });
    });
    document.querySelectorAll('.board-filter-btn').forEach(function(b) {
      b.addEventListener('click', function(e) {
        activeFilter = e.target.getAttribute('data-filter');
        renderBoards();
      });
    });
    const si = document.getElementById('movie-search-input');
    if (si) si.addEventListener('input', renderBoards);
    const archBtn = document.getElementById('toggle-archive-all-btn');
    if (archBtn) archBtn.addEventListener('click', function() {
      window._showAllArchive = !window._showAllArchive;
      renderBoards();
    });
    const ss = document.getElementById('board-sort-select');
    if (ss) ss.addEventListener('change', renderBoards);
    const ab = document.getElementById('toggle-auto-sync-btn');
    if (ab) ab.addEventListener('click', function() {
      autoSyncEnabled = !autoSyncEnabled;
      ab.textContent = autoSyncEnabled ? 'AUTO: ON' : 'AUTO: PAUSED';
    });
    const cb = document.getElementById('toggle-currency-btn');
    if (cb) cb.addEventListener('click', function() {
      isUsdCurrency = !isUsdCurrency;
      cb.textContent = isUsdCurrency ? '$ USD' : '₹ INR';
      updateLiveNumbersDisplay(true);
    });
  }
//
